#!/bin/sh
# Tier-1 gate: UI interaction COVERAGE (the change-69 lesson: a disabled-admin-
# inputs regression shipped through five green gates because nothing exercised
# the rendered DOM). A working-tree diff that touches user-facing paths must
# carry a matching interaction check in state/ui-checks.json for EVERY touched
# user-facing file. The checks themselves are EXECUTED against the deployed app
# by the browser smoke connector (per-role login, enabled/disabled assertions,
# typed input persists, zero console errors) — this gate enforces that they
# EXIST and parse. Deterministic; no AI.
if ! command -v git >/dev/null 2>&1 || ! git rev-parse --git-dir >/dev/null 2>&1; then
  echo "ui-interaction: no git tree; skipped."
  exit 0
fi
{ git diff --name-only HEAD 2>/dev/null; git ls-files --others --exclude-standard 2>/dev/null; } \
  | sort -u | grep -v '^state/changes/' > /tmp/ui-gate-changed.txt || true
if [ ! -s /tmp/ui-gate-changed.txt ]; then
  echo "ui-interaction: no working-tree changes; skipped."
  exit 0
fi
if ! command -v node >/dev/null 2>&1; then
  echo "ui-interaction: FAIL - node is required to evaluate ui-check coverage."
  exit 1
fi
node <<'UIGATE'
const fs = require('fs');
const changed = fs.readFileSync('/tmp/ui-gate-changed.txt', 'utf8').split('\n').map(s => s.trim()).filter(Boolean);
// User-facing paths — mirror of the browser smoke trigger globs.
const uiRe = [/^public\//i, /\.(html|css|scss|jsx|tsx)$/i, /(^|\/)views\//i, /(^|\/)templates\//i];
const uiFiles = changed.filter(f => uiRe.some(re => re.test(f)));
if (!uiFiles.length) { console.log('ui-interaction: no user-facing paths in this change; skipped.'); process.exit(0); }
let spec;
try { spec = JSON.parse(fs.readFileSync('state/ui-checks.json', 'utf8')); }
catch (err) {
  console.log('ui-interaction: FAIL - user-facing change (' + uiFiles.slice(0, 5).join(', ') + ') but state/ui-checks.json is missing or invalid: ' + err.message);
  // The WHOLE FILE, not just advice about it. This branch used to say
  // "add interaction checks covering the touched screens" and stop, so a
  // build that had never written one went and reverse-engineered the format
  // from this gate's own source (project 42 read /srv/gates/01-ui-interaction.sh
  // and grepped the filesystem for the schema). The platform owns this format;
  // making each build rediscover it is a round-trip the platform can just not
  // charge for.
  console.log('Write state/ui-checks.json. It is one JSON file; this is the whole shape:');
  console.log('{');
  console.log('  "users": [{ "role": "admin", "email": "admin@fixture.invalid", "password": "<12+ chars>" }],');
  console.log('  "checks": [{');
  console.log('    "id": "notes-list-loads",');
  console.log('    "name": "The notes list renders and search filters it",');
  console.log('    "paths": ["public/app.html", "public/n7.js"],');
  console.log('    "login": "admin@fixture.invalid",');
  console.log('    "page": "/",');
  console.log('    "steps": [');
  console.log('      { "expect_visible": "#note-grid" },');
  console.log('      { "fill": "#search", "value": "groceries", "expect_value": true },');
  console.log('      { "expect_text": "#note-grid", "contains": "Groceries" },');
  console.log('      { "click": "#new-note" },');
  console.log('      { "expect_enabled": "#save" }');
  console.log('    ]');
  console.log('  }]');
  console.log('}');
  console.log('Copy that verbatim and edit it - it is valid JSON exactly as printed.');
  console.log('"paths" are globs saying which files a check covers; EVERY user-facing file');
  console.log('you touched needs at least one check matching it. "login" names a user from');
  console.log('"users" - omit it to run the check SIGNED OUT.');
  console.log('One assertion per step. Steps: expect_visible / expect_enabled / expect_disabled /');
  console.log('expect_absent / expect_text (+contains) / fill (+value) / click. The connector runs');
  console.log('these against the DEPLOYED app per role, and any console error fails the check.');
  process.exit(1);
}
const checks = Array.isArray(spec.checks) ? spec.checks : [];
const bad = checks.filter(c => !c || !c.id || !c.page || !Array.isArray(c.paths) || !c.paths.length || !Array.isArray(c.steps) || !c.steps.length);
if (bad.length) {
  console.log('ui-interaction: FAIL - malformed check(s) in state/ui-checks.json: ' + bad.map(c => (c && c.id) || '(no id)').join(', '));
  process.exit(1);
}
// STEP VALIDATION — the same rules the post-deploy connector applies.
//
// This gate used to check only that id/page/paths/steps EXIST. So a build
// iterated to green here, deployed, and only then met the strict parser: two
// projects in a row shipped a state/ui-checks.json that passed this gate and
// then failed after deploy, once for the step spelling and once for a step
// with no recognised action at all. A validator the model can satisfy without
// being correct teaches the wrong thing. The error now arrives BEFORE the
// deploy, and it names the offending step's own keys so it is fixable in one
// pass instead of guessed at.
const KINDS = ['expect_enabled', 'expect_disabled', 'expect_visible', 'expect_text', 'fill', 'click'];
const stepProblems = [];
for (const c of checks) {
  let lastFill = null;
  c.steps.forEach((st, i) => {
    const where = '"' + c.id + '" step ' + (i + 1);
    if (!st || typeof st !== 'object') { stepProblems.push(where + ' is not an object'); return; }
    const canonical = KINDS.filter(k => st[k] !== undefined);
    if (canonical.length > 1) { stepProblems.push(where + ' asserts more than one thing: ' + canonical.join(', ')); return; }
    if (canonical.length === 1) {
      const kind = canonical[0];
      if (typeof st[kind] !== 'string' || !st[kind].trim()) stepProblems.push(where + ' (' + kind + ') needs a selector string');
      if (kind === 'fill' && typeof st.value !== 'string') stepProblems.push(where + ' (fill) needs a value string');
      if (kind === 'expect_text' && typeof st.contains !== 'string') stepProblems.push(where + ' (expect_text) needs a contains string');
      lastFill = kind === 'fill' ? st[kind] : null;
      return;
    }
    // The conventional { action, selector } spelling, which the parser accepts.
    const action = typeof st.action === 'string' ? st.action.trim() : null;
    if (!action) {
      stepProblems.push(where + ' has none of ' + KINDS.join(', ') + ' and no "action" — its keys are: ' + Object.keys(st).join(', '));
      return;
    }
    if (typeof st.selector !== 'string' || !st.selector.trim()) { stepProblems.push(where + ' ("' + action + '") needs a selector string'); return; }
    if (action === 'expect_value') {
      if (lastFill !== st.selector) stepProblems.push(where + ' (expect_value) must follow a fill of the same control');
      return;
    }
    if (!KINDS.includes(action)) {
      stepProblems.push(where + ': unknown action "' + action + '" - one of ' + KINDS.join(', ') + ', expect_value');
      return;
    }
    if (action === 'fill' && typeof (st.value ?? st.text) !== 'string') stepProblems.push(where + ' (fill) needs a value/text string');
    if (action === 'expect_text' && typeof (st.contains ?? st.text) !== 'string') stepProblems.push(where + ' (expect_text) needs a contains/text string');
    lastFill = action === 'fill' ? st.selector : null;
  });
}
if (stepProblems.length) {
  console.log('ui-interaction: FAIL - state/ui-checks.json has step(s) the browser connector cannot run:');
  stepProblems.slice(0, 12).forEach(p => console.log('  - ' + p));
  console.log('A step is either {"expect_visible": "#sel"} / {"fill": "#sel", "value": "x"} / {"expect_text": "#sel", "contains": "x"}');
  console.log('or {"action": "expect_visible", "selector": "#sel"}. Both spellings work; a step must be exactly one assertion.');
  process.exit(1);
}
// Tiny glob: ** crosses directories, * stays within a path segment.
function glob(g) {
  let re = '';
  for (let i = 0; i < g.length; i++) {
    const c = g[i];
    if (c === '*') {
      if (g[i + 1] === '*') { i++; if (g[i + 1] === '/') { i++; re += '(?:.*/)?'; } else re += '.*'; }
      else re += '[^/]*';
    } else re += /[.+?^$"{}()|[\]\\/]/.test(c) ? '\\' + c : c;
  }
  return new RegExp('^' + re + '$', 'i');
}
const uncovered = uiFiles.filter(f => !checks.some(c => c.paths.some(p => glob(p).test(f))));
if (uncovered.length) {
  console.log('ui-interaction: FAIL - user-facing file(s) with NO matching interaction check:');
  uncovered.forEach(f => console.log('  - ' + f));
  console.log('Every touched screen needs a state/ui-checks.json check: per-role enabled/disabled assertions, typed input persists (fill + expect_value), write-only secrets enable after Replace, zero console errors.');
  process.exit(1);
}
console.log('ui-interaction: OK - ' + uiFiles.length + ' user-facing file(s) covered by ' + checks.length + ' check(s); the browser smoke connector executes the matching checks after deploy.');
UIGATE
exit $?

#!/bin/sh
# Tier-1 gate: acceptance spec (cycle-94 lesson: a bug-fix cycle "succeeded"
# with green gates while the defect was never reproduced). Every cycle declares
# WHAT done means in state/acceptance.json; this gate enforces the STATIC half:
# the spec exists and parses; a bugfix carries a defect_tag + an existing
# regression test carrying that tag; a declared integration contract test must
# exercise REAL logic (no mocked transport); declared ui ids exist in
# state/ui-checks.json. The DYNAMIC halves are enforced elsewhere: red->green
# by the runner (finish is rejected without an observed red test gate), live
# acceptance checks by the post-deploy browser connector. Deterministic; no AI.
if [ ! -f package.json ] && [ ! -d src ]; then
  echo "acceptance: no app yet (scaffold pending); skipped."
  exit 0
fi
if ! command -v node >/dev/null 2>&1; then
  echo "acceptance: FAIL - node is required to evaluate the acceptance spec."
  exit 1
fi
node <<'ACCGATE'
const fs = require('fs');
let spec;
try { spec = JSON.parse(fs.readFileSync('state/acceptance.json', 'utf8')); }
catch (e) {
  console.log('acceptance: FAIL - state/acceptance.json is missing or invalid: ' + e.message);
  console.log('Write it FIRST: {"task": "...", "kind": "bugfix|feature|chore", "defect_tag": "...", "tests": [...], "integration": {"contract_test": "..."}, "ui": [...]}');
  process.exit(1);
}
const kind = String(spec.kind || '').toLowerCase();
if (!String(spec.task || '').trim() || !['bugfix', 'feature', 'chore'].includes(kind)) {
  console.log('acceptance: FAIL - task and kind (bugfix|feature|chore) are required.');
  process.exit(1);
}
const problems = [];
if (kind === 'bugfix') {
  if (!/^[a-z0-9][a-z0-9-]{2,80}$/.test(String(spec.defect_tag || ''))) problems.push('a bugfix needs a defect_tag slug (e.g. "defect-adp-mtls-mismatch")');
  const tests = Array.isArray(spec.tests) ? spec.tests : [];
  if (!tests.length) problems.push('a bugfix needs at least one regression test path in tests[]');
  for (const t of tests) if (!fs.existsSync(t)) problems.push('declared test does not exist: ' + t);
  if (spec.defect_tag && tests.length && !tests.some(t => { try { return fs.readFileSync(t, 'utf8').includes(spec.defect_tag); } catch { return false; } })) {
    problems.push('no declared test carries the defect_tag "' + spec.defect_tag + '" - tag the regression test to the defect');
  }
}
if (spec.integration) {
  const ct = String(spec.integration.contract_test || '');
  if (!ct || !fs.existsSync(ct)) problems.push('integration.contract_test is missing or does not exist: ' + ct);
  else {
    const body = fs.readFileSync(ct, 'utf8');
    if (/\b(vi|jest)\.mock\s*\(|injectTransport\s*\(|fakeTransport|mockTransport/i.test(body)) {
      problems.push('the integration contract test mocks the transport - it must run the REAL integration logic (e.g. actual cert/key matching + https.Agent) against local fixtures or a stub server. No integration is validated by mocks alone.');
    }
  }
}
const ui = Array.isArray(spec.ui) ? spec.ui : [];
if (ui.length) {
  let ids = null;
  try { ids = (JSON.parse(fs.readFileSync('state/ui-checks.json', 'utf8')).checks || []).map(c => c.id); }
  catch { problems.push('acceptance declares ui ids but state/ui-checks.json is missing/invalid'); }
  if (ids) for (const id of ui) if (!ids.includes(id)) problems.push('acceptance ui id not defined in state/ui-checks.json: ' + id);
}
if (problems.length) {
  console.log('acceptance: FAIL');
  problems.forEach(p => console.log('  - ' + p));
  process.exit(1);
}
console.log('acceptance: OK - ' + kind + ' spec declared; red->green is verified by the runner, live checks by the post-deploy connector.');
ACCGATE
exit $?

#!/bin/sh
# Tier-1 gate: COMPONENT REUSE (the request-36 lesson: a build re-implemented the
# first-visit super-admin bootstrap that the installed auth component already
# shipped, then spent five attempts fighting gates on a feature that was done).
# state/components.json records each installed component's API contract and its
# installed file paths. A working-tree diff that re-registers a component's
# endpoint OUTSIDE the component's own files, or adds a parallel copy of a
# component file while the original is still on disk, is a REIMPLEMENTATION:
# wire the component instead. Edits INSIDE a component's files are adaptation
# and pass. Deterministic; no AI.
# Waiver protocol (never dodge the detector): if a flagged duplication is
# genuinely justified, add the exact file path to
# state/component-reuse-allowlist.txt as a distinct reviewed act (halt option /
# deviation explaining WHY), so an admin approves the waiver - not the dodge.
[ -f state/components.json ] || { echo "component-reuse: no state/components.json (no installed components); skipped."; exit 0; }
if ! command -v git >/dev/null 2>&1 || ! git rev-parse --git-dir >/dev/null 2>&1; then
  echo "component-reuse: no git tree; skipped."
  exit 0
fi
{ git diff --name-only HEAD 2>/dev/null; git ls-files --others --exclude-standard 2>/dev/null; } \
  | sort -u | grep -v '^state/changes/' > /tmp/cr-gate-changed.txt || true
if [ ! -s /tmp/cr-gate-changed.txt ]; then
  echo "component-reuse: no working-tree changes; skipped."
  exit 0
fi
if ! command -v node >/dev/null 2>&1; then
  echo "component-reuse: FAIL - node is required to evaluate component reuse."
  exit 1
fi
node <<'CRGATE'
const fs = require('fs');
const changedPath = process.env.CR_CHANGED || '/tmp/cr-gate-changed.txt';
const changed = fs.readFileSync(changedPath, 'utf8').split('\n').map(s => s.trim()).filter(Boolean);
let doc;
try { doc = JSON.parse(fs.readFileSync('state/components.json', 'utf8')); }
catch (err) { console.log('component-reuse: state/components.json unreadable (' + err.message + '); skipped.'); process.exit(0); }
const comps = (Array.isArray(doc.entries) ? doc.entries : []).filter(e => e && e.key && (e.status === 'installed' || e.installed_at));
if (!comps.length) { console.log('component-reuse: no installed components; skipped.'); process.exit(0); }
// Reviewed waivers: exact changed-file paths an admin approved via the gate-waiver
// protocol (a halt/deviation naming WHY), one per line, # comments.
let allow = new Set();
try {
  allow = new Set(fs.readFileSync('state/component-reuse-allowlist.txt', 'utf8')
    .split('\n').map(s => s.trim()).filter(s => s && !s.startsWith('#')));
} catch { /* no allowlist */ }
// Paths owned by installed components - edits there are adaptation, never flagged.
const compFiles = new Set();
for (const c of comps) for (const f of (c.files || [])) compFiles.add(String(f));
// Normalize an express-style path: params collapse to :x, trailing slash dropped.
const norm = p => (String(p || '').trim().replace(/:[A-Za-z_$][\w$]*/g, ':x').replace(/\/+$/, '')) || '/';
const segs = p => norm(p).split('/').filter(Boolean);
const endpoints = [];
for (const c of comps) for (const a of (c.api || [])) {
  if (a && a.path) endpoints.push({ key: c.key, method: String(a.method || 'GET').toUpperCase(), path: norm(a.path) });
}
// Basename duplication: generic names and numbered migrations are exempt (a
// same-named index.ts is convention, not duplication; migrations renumber).
const GENERIC = /^(index|routes?|router|config|types?|utils?|helpers?|app|main|server|schema|styles?|constants?)\.[a-z]+$/i;
const base = p => String(p).split('/').pop();
const compBase = new Map();
for (const f of compFiles) {
  const b = base(f);
  if (!GENERIC.test(b) && !/^\d+[_-]/.test(b) && !compBase.has(b)) compBase.set(b, f);
}
const CODE = /\.(m?[jt]s|c[jt]s|[jt]sx)$/i;
const viol = new Set();
for (const f of changed) {
  if (compFiles.has(f) || allow.has(f)) continue;
  // (a) a component endpoint re-registered outside the component's files. The
  // receiver must LOOK like an express app/router (app / router / xRouter / r) -
  // client code CALLING a component endpoint (api.post/axios.post/fetch) is the
  // wiring we WANT, never flagged. Exact full-path match always flags; a suffix
  // match (router mounted at a prefix) needs >=2 segments so a generic
  // one-segment path ('/status') never false-positives. Method must match
  // (.all/.route match any method).
  if (CODE.test(f) && fs.existsSync(f)) {
    const src = fs.readFileSync(f, 'utf8');
    const re = /\b(?:app|r|router|[A-Za-z_$][\w$]*[Rr]outer)\s*\.\s*(get|post|put|patch|delete|all|route)\s*\(\s*(['"`])([^'"`\n]+)\2/g;
    let m;
    while ((m = re.exec(src))) {
      const method = m[1].toUpperCase();
      const reg = norm(m[3]);
      if (!reg.startsWith('/')) continue;
      for (const ep of endpoints) {
        if (method !== 'ALL' && method !== 'ROUTE' && ep.method !== method) continue;
        const exact = reg === ep.path;
        const suffix = segs(reg).length >= 2 && ep.path.endsWith(reg);
        if (exact || suffix) viol.add(f + ': registers ' + method + ' ' + m[3] + ' - already provided by installed component "' + ep.key + '" (' + ep.method + ' ' + ep.path + '). Wire the component; do not re-implement its endpoint.');
      }
    }
  }
  // (b) a parallel copy of a component file: same basename, component's original
  // still on disk (a move/rename does not flag - the original would be gone).
  const b = base(f);
  if (compBase.has(b) && f !== compBase.get(b) && fs.existsSync(f) && fs.existsSync(compBase.get(b))) {
    viol.add(f + ': duplicates installed component file ' + compBase.get(b) + ' (same basename, both on disk). Adapt the component\'s file or wire it; do not keep a parallel copy.');
  }
}
if (viol.size) {
  console.log('component-reuse: FAIL - this change re-implements capability an installed component already provides:');
  for (const v of viol) console.log('  - ' + v);
  console.log('Reuse the component (get_component <key> for integration notes; its files and endpoints are already in the source tree). If this duplication is genuinely justified, add the exact file path to state/component-reuse-allowlist.txt as a reviewed waiver with a halt/deviation explaining why - never restructure code to dodge this gate (constitution SS12).');
  process.exit(1);
}
console.log('component-reuse: OK - ' + changed.length + ' changed file(s) checked against ' + comps.length + ' installed component(s); no reimplementation detected.');
CRGATE
exit $?
